import math


def _is_null(v):
    return v is None or v != v


def _type_ok(v, t):
    if t == "int":
        return isinstance(v, int) and not isinstance(v, bool)
    if t == "float":
        return isinstance(v, (int, float)) and not isinstance(v, bool)
    if t == "str":
        return isinstance(v, str)
    raise ValueError("unknown type: " + str(t))


def validate_batch(rows, schema):
    """Return a list of violation dicts; an empty list means the batch is clean.

    schema maps column -> dict with optional keys: type ('int'|'float'|'str'),
    min, max, allowed (collection), max_null_rate (default 0.0),
    severity ('error' or 'warn', default 'error').
    A missing key or None/NaN counts as null.
    """
    if not rows:
        return [{"column": None, "check": "empty_batch", "severity": "error",
                 "detail": "no rows"}]
    out = []
    n = len(rows)
    for col in sorted(schema):
        spec = schema[col]
        sev = spec.get("severity", "error")
        if not any(col in r for r in rows):
            out.append({"column": col, "check": "missing_column",
                        "severity": "error", "detail": "absent from every row"})
            continue
        values = [r.get(col) for r in rows]
        non_null = [v for v in values if not _is_null(v)]
        null_rate = (n - len(non_null)) / n
        if null_rate > spec.get("max_null_rate", 0.0):
            out.append({"column": col, "check": "null_rate", "severity": sev,
                        "detail": "null rate %.3f > %.3f"
                        % (null_rate, spec.get("max_null_rate", 0.0))})
        if "type" in spec:
            bad = [v for v in non_null if not _type_ok(v, spec["type"])]
            if bad:
                out.append({"column": col, "check": "type", "severity": "error",
                            "detail": "%d value(s) not %s" % (len(bad), spec["type"])})
                continue
        if "min" in spec or "max" in spec:
            lo = spec.get("min", -math.inf)
            hi = spec.get("max", math.inf)
            bad = [v for v in non_null
                   if not (isinstance(v, (int, float)) and not isinstance(v, bool)
                           and lo <= v <= hi)]
            if bad:
                out.append({"column": col, "check": "range", "severity": sev,
                            "detail": "%d value(s) outside [%s, %s]" % (len(bad), lo, hi)})
        if "allowed" in spec:
            allowed = set(spec["allowed"])
            bad = [v for v in non_null if v not in allowed]
            if bad:
                out.append({"column": col, "check": "allowed", "severity": sev,
                            "detail": "unseen values: %s" % sorted(set(map(str, bad)))})
    return out


def has_errors(violations):
    return any(v["severity"] == "error" for v in violations)

